import React, { useRef } from 'react';
import { FileUpload } from 'primereact/fileupload';
import { Toast } from 'primereact/toast';

export default function Basic() {
    const toast = useRef(null);

    const onSelect = (event) => {
        const files = event.files;
        if (files && files.length > 0) {
            toast.current.show({ 
                severity: 'info', 
                summary: 'File Selected', 
                detail: `${files.length} file(s) selected`,
                life: 3000 
            });
        }
    };

    const onUpload = (event) => {
        toast.current.show({ 
            severity: 'success', 
            summary: 'Success', 
            detail: 'File Uploaded',
            life: 3000 
        });
    };

    const onError = (event) => {
        toast.current.show({ 
            severity: 'error', 
            summary: 'Error', 
            detail: event.error || 'Upload failed',
            life: 3000 
        });
    };
        
    return (
        <>
            <Toast ref={toast} />
            <FileUpload 
                mode="basic" 
                name="demo[]" 
                url="/api/upload" 
                accept="image/*" 
                maxFileSize={1000000} 
                onSelect={onSelect}
                onUpload={onUpload}
                onError={onError}
            />
        </>  
    )

}